Q: How to push JSON data into array with 2 level or n level A: <p>You can't <code>push</code> anything onto <code>name[0]</code> as it is not an array but you can still assign elements with number's to it and create your own push.</p>

<pre><code>var makePushable = function (obj) {
  obj.push = function (item) {
    this[this.length] = item;
    this.length++;
  };
  obj.length = 0; //Keep track of how many elements
}

var name = [];
name.push({ name: "Gareth" });

makePushable(name[0]);
name[0].push({ name: "john" });
name[0].push({ name:"dolly" });
</code></pre>

<p>And we get:</p>

<pre><code>name[0]    ---&gt; {
    name:"gareth",

    0: {name:"john"},
    1: {name:"dolly"},

    length: 2,
    push: function () { ... }
}
name[0][0] ---&gt; {name:"john"}
name[0][1] ---&gt; {name:"dolly"}
</code></pre>

<p>If you don't want <code>push</code> and <code>length</code> to show up on <code>for ( prop in xxx ) if (xxx.hasOwnProperty(prop))</code>, you could make a class like so:</p>

<pre><code>var Pushable = function (obj) {
  for (var i in obj) {
    this[i] = obj[i];
  }
  Object.setPrototypeOf(this, {
    push: function (item) {
      this[this.length] = item;
      Object.getPrototypeOf(this).length++;
    },
    length: 0
  });
};

Pushable.prototype.push = function (item) {
  this[this.length] = item;
  Object.getPrototypeOf(this).length++;
};
Pushable.prototype.length = 0;

var name = [];
name.push(new Pushable({ name:"Gareth" }));
name[0].push(new Pushable({ name: "john" }));
name[0].push(new Pushable({ name:"dolly" }));
name[0][1].push(new Pushable({ name:"last kid" }));
</code></pre>

<p>You could make the <code>push</code> function, automatically create a <code>Pushable</code> class for you if you wanted.</p>
